<template>
    <div class="cart">
      <div class="scroll-wrapper">
        <div class="goods-list" v-if="cartInfo.list">
          <div class="goods-wrapper" v-for="(item, index) in cartInfo.list" :key="item.goods_id" :class="{'active': isTranslate && translateIndex == index}">
            <div class="goods-item" @touchstart.capture="touchStart($event, index)" @touchend.capture="touchEnd($event, index)" @click="checkGoodsDetail(item.goods_id)">
              <div class="select-box" @click.stop="item.status == 1 ? selectItem(index) : ''">
                <span v-if="item.status == 1">
                  <i class="icon iconfont unselected" v-show="item.checked == 0" >&#xe72f;</i>
                  <i class="icon iconfont selected main-color-font" v-show="item.checked == 1">&#xe606;</i>
                </span>
                <i v-else class="banned"></i>
              </div>
              <div class="img-box">
                <img class="goods-img" :src="item.image" alt="">
              </div>
              <div class="desc-box">
                <div class="name">{{ item.limit_buy == 0 ? '' : '【限购'+item.limit_buy+'份】' }}{{item.name}}</div>
                <div class="packing-fee" v-if="item.packing_fee > 0">打包费 ¥{{item.packing_fee}}</div>
                <div class="price-box">
                  <div>
                    <span class="now now-icon main-color-font">¥</span>
                    <span class="now main-color-font">{{item.price}}</span>
                    <span class="old">¥{{item.old_price}}</span>
                  </div>
                  <AddToCart v-if="item.status == 1" type="big" :goodsId="item.goods_id" from="cart"/>
                </div>
              </div>
              <div class="close-buy" v-if="item.status == 2">
                <div class="icon-box">
                  <div class="icon">已下架</div>
                </div>
              </div>
            </div>
            <div class="delete" @click.stop="deleteGoods(index)">删除</div>
          </div>
        </div>
        <div class="cart-empty" v-if="isComplete && !cartInfo.list">
          <div class="img-box"><img src="./imgs/cart_empty.jpg" alt=""></div>
          <div>购物车空空如也，赶紧去逛逛吧~</div>
        </div>
        <DiscountGoods from="cart" />
      </div>
      <div class="footer">
        <div class="price-box">
          <div class="left" v-show="cartInfo.list && cartInfo.list.length > 0" @click="selectAll">
            <i class="icon iconfont unselected" v-show="!selectedAll">&#xe72f;</i>
            <i class="icon iconfont selected main-color-font" v-show="selectedAll">&#xe606;</i>
            <span>全选</span>
          </div>
          <div class="right">
            <span>合计：</span>
            <span class="num main-color-font">¥{{cartInfo.all_money}}</span>
          </div>
        </div>
        <div class="btn main-color-bg" @click="saveOrder">去结算({{cartInfo.select_nums}})</div>
      </div>
    </div>
</template>

<script>
import PubSub from 'pubsub-js'
import DiscountGoods from '../../components/DiscountGoods/DiscountGoods'
import AddToCart from '../../components/AddToCart/AddToCart'
export default {
  name: 'Cart',
  data () {
    return {
      startX: 0,
      endX: 0,
      isTranslate: false,
      translateIndex: -1,
      cartInfo: { select_nums: 0, all_money: 0, all_nums: 0 }, // 购物车数据
      leader_id: '',
      selectedAll: true,
      selectInfo: {},
      isComplete: false
    }
  },
  created () {
    if (!this.$util.storage.get('ticket')) {
      this.$util.checkLogin()
    } else {
      this.leader_id = this.$util.storage.get('leader_id')
      this.getCart()

      // 订阅购物车数量变化
      PubSub.subscribe('cartInfo', (event, data) => {
        if (data.needUpdate && data.goodsNum == 1) {
          this.getCart()
        } else {
          this.cartInfo.select_nums = data.selectNum
          this.cartInfo.all_money = data.money
          if (data.needUpdate) {
            for (let i = 0; i < this.cartInfo.list.length; i++) {
              if (this.cartInfo.list[i].goods_id == data.goodsId) {
                this.cartInfo.list.splice(i, 1)
                break
              }
            }
            if (this.cartInfo.list.length == 0) {
              this.cartInfo.list = undefined
            }
          }
        }
      })
    }
  },
  beforeRouteEnter (to, from, next) {
    if (from.path == '/dayBuy') {
      to.meta.showFooter = false
    } else {
      to.meta.showFooter = true
    }
    next()
  },
  methods: {
    // 点击结算
    async saveOrder () {
      let res = await this.$api.saveOrder({ leader_id: this.leader_id })
      if (!res) return
      this.$global.orderId = res.order_id
      this.$router.push({ path: '/confirm', query: { leader_id: this.leader_id, order_id: res.order_id } })
    },
    // 查看商品详情
    checkGoodsDetail (id) {
      // this.getCart()
      this.$router.push({ path: '/goods', query: { goodsId: id, leaderId: this.leader_id } })
    },
    // 全选
    selectAll () {
      this.saveCart({
        leader_id: this.leader_id,
        goods_id: 0,
        nums: 0,
        checked: !this.selectedAll ? 1 : 0
      })
    },
    // 选择某个商品
    selectItem (index) {
      let goodsId = this.cartInfo.list[index].goods_id
      this.saveCart({
        leader_id: this.leader_id,
        goods_id: goodsId,
        nums: this.$global.goodsNumObj[goodsId].num,
        checked: this.cartInfo.list[index].checked == 1 ? 0 : 1
      }, index)
    },
    // 删除商品
    deleteGoods (index) {
      this.$messageBox.confirm('确认从购物车中删除该商品？').then(action => {
        if (action == 'confirm') {
          this.saveCart({
            leader_id: this.leader_id,
            goods_id: this.cartInfo.list[index].goods_id,
            nums: 0,
            checked: 0
          }, index)
        }
      }, () => {
        this.restSlide()
      })
    },
    // 滑动开始
    touchStart (e, index) {
      // 记录初始位置
      this.startX = e.touches[0].clientX
    },
    // 滑动结束
    touchEnd (e, index) {
      // 记录结束位置
      this.endX = e.changedTouches[0].clientX
      this.restSlide()
      // 左滑
      if (!this.isTranslate && this.startX - this.endX > 60) {
        this.translateIndex = index
        this.isTranslate = true
      }
      // 右滑
      if (this.isTranslate && this.startX - this.endX < -60) {
        this.translateIndex = index
        this.isTranslate = false
      }
      this.startX = 0
      this.endX = 0
    },
    // 复位滑动状态
    restSlide () {
      // 复位
      this.isTranslate = false
      this.translateIndex = -1
    },
    // 获取购物车列表数据
    async getCart () {
      let res = await this.$api.getCart({ leader_id: this.leader_id })
      // 抛出错误
      if (!res) return
      this.isComplete = true
      let obj = {
        totalPrice: 0,
        totalNum: 0,
        selectNum: 0
      }
      let cartInfo = {
        num: 0,
        selectNum: 0,
        money: 0,
        allNeedRefresh: true
      }
      if (res.list) {
        this.selectedAll = res.select_nums == res.all_nums
        obj.selectNum = res.select_nums
        obj.totalPrice = res.all_money
        obj.totalNum = res.all_nums
        res.list.map(item => {
          obj[item.goods_id] = { num: item.cart_nums, checked: item.checked }
        })
        this.cartInfo = res

        // 发布消息：购物车总数变化
        cartInfo = {
          num: res.all_nums,
          selectNum: res.select_nums,
          money: res.all_money,
          allNeedRefresh: true
        }
      }
      this.$global.goodsNumObj = obj
      PubSub.publish('cartInfo', cartInfo)
    },
    // 修改购物车数据
    async saveCart (param, index) {
      let res = await this.$api.saveCart(param)
      // 抛出错误
      if (!res) return

      this.selectedAll = res.select_nums == res.all_nums
      let obj = JSON.parse(JSON.stringify(this.$global.goodsNumObj))
      if (param.goods_id !== 0 && param.nums === 0) {
        // 删除购物车列表中该商品
        this.cartInfo.list.splice(index, 1)
        this.restSlide()
        if (this.cartInfo.list.length == 0) {
          this.cartInfo.list = undefined
        }
        obj[param.goods_id] = null
      } else if (param.goods_id !== 0) {
        // 单选某个商品
        obj[param.goods_id].checked = param.checked
        this.cartInfo.list[index].checked = param.checked
      } else {
        // 全选按钮
        this.cartInfo.list.map(item => {
          item.checked = param.checked
        })
        for (var key in obj) {
          if (obj[key] && obj[key].num) {
            obj[key].checked = param.checked
          }
        }
      }
      obj.selectNum = res.select_nums
      obj.totalNum = res.all_nums
      obj.totalPrice = res.all_money
      this.$global.goodsNumObj = obj
      // 发布消息：购物车总数变化
      let cartInfo = {
        num: res.all_nums,
        selectNum: res.select_nums,
        money: res.all_money,
        goodsId: param.goods_id,
        goodsNum: param.nums,
        checked: param.checked
      }
      PubSub.publish('cartInfo', cartInfo)
    }
  },
  components: {
    DiscountGoods,
    AddToCart
  }
}
</script>

<style lang="stylus" scoped>
.cart
  background #f2f2f2
  position relative
  .scroll-wrapper
    height calc(100% - 45px)
    overflow-y auto
    overflow-x hidden
    -webkit-overflow-scrolling touch
    .goods-list
      background #fff
      padding 0 10px
      border-bottom 1PX solid #efefef
      margin-bottom 30px
      .goods-wrapper
        position relative
        transform translateX(0)
        transition all ease .3s
        &.active
          transform translateX(-60px)
        .goods-item
          width 100%
          flex-shrink 0
          flexbox()
          padding 15px 0
          border-bottom 1PX solid #efefef
          position relative
          &:last-child
            border-bottom none
          .select-box
            line-height 80px
            margin-right 10px
            .icon
              font-size 24px
              &.selected
                color $color-main
              &.unselected
                color #bbb
            .banned
              display inline-block
              width 18px
              height 18px
              border-radius 50%
              border 2px solid #bbb
              background #f2f2f2
          .img-box
            width 80px
            height 80px
            overflow hidden
            flex-shrink 0
            position relative
            .goods-img
              width 100%
              height 100%
            .icon
              position absolute
              top 0
              left 0
              width 30px
          .desc-box
            padding-left 10px
            flex-grow 1
            line-height 1.2
            position relative
            .packing-fee
              line-height 1.5
              color #999
            .name
              font-size 14px
              ellipsis(2)
              max-height 32px
            .price-box
              position absolute
              bottom -5px
              left 10px
              right 0px
              flexbox()
              justify-content space-between
              align-items center
              line-height 1.3
              .now
                font-size 18px
                font-weight bold
                color $color-main
                margin-right 5px
              .now-icon
                margin-right 0
                font-size 12px
              .old
                color #999999
                text-decoration line-through
              .num
                font-size 12px
                color #999999
              .cart-icon
                width 30px
                height 30px
                text-align center
                line-height 30px
                border-radius 50%
                background $color-main
                background #fff
                width auto
                .num-box
                  color $color-main
                  .num
                    color #000
                    padding 0 8px
                    font-size 16px
                    position relative
                    top -3px
                  .icon
                    font-size 26px
                    position relative
                    &:after
                      content ''
                      position absolute
                      top -5px
                      left -5px
                      right -5px
                      bottom -5px
          .close-buy
            position absolute
            top 0
            left 0
            right 0
            bottom 0
            background rgba(255, 255, 255, .4)
            padding 15px 0 15px 34px
            .icon-box
              width 80px
              height 80px
              padding 10px
              box-sizing border-box
              position relative
              .icon
                width 100%
                height 100%
                background rgba(0, 0, 0, .5)
                color #fff
                border-radius 50%
                flexbox()
                justify-content center
                align-items center
                font-size 14px
        .delete
          position absolute
          right -60px
          top 0
          bottom 0
          width 50px
          font-size 16px
          background $color-main
          color #fff
          flexbox()
          align-items center
          justify-content center
    .cart-empty
      background #fff
      color #999
      text-align center
      padding 60px 0
      .img-box
        width 200px
        height 200px
        margin 0 auto 20px
        img
          width 100%
          height 100%
  .footer
    height 45px
    line-height 45px
    position absolute
    bottom 0
    left 0
    right 0
    background #fff
    box-shadow 0 -5px 5px -5px #ddd
    .price-box
      width calc(100% - 120px)
      float left
      flexbox()
      justify-content space-between
      align-items center
      font-size 14px
      padding-right 15px
      box-sizing border-box
      .left
        .icon
          padding 10px
          padding-left 15px
          font-size 24px
          vertical-align middle
          &.selected
            color $color-main
          &.unselected
            color #bbb
      .right
        padding-left 15px
        .num
          color $color-main
          font-weight 500
          font-size 16px
    .btn
      background $color-main
      width 120px
      text-align center
      float left
      font-size 16px
      color #fff
</style>
